// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        vm.assume(ts > 0);
        vm.assume(actor != address(0) && actor != address(c));
        blockNumber = bound(blockNumber, 0, 10**6);
        vm.roll(blockNumber);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        // General rule: every accepted 10-ether call on a block number divisible by 15
        // drains the contract entirely (balance == 0); on other blocks the rule is vacuous.
        assertTrue(ok && (blockNumber % 15 != 0 || address(c).balance == 0));
    }
}
